import{_ as t,c as e,o as r,a}from"./app.19f3f8f0.js";const u=JSON.parse('{"title":"ReplyBridge","description":"","frontmatter":{},"headers":[{"level":2,"title":"Start here (from Instagram)","slug":"start-here-from-instagram","link":"#start-here-from-instagram","children":[]},{"level":2,"title":"What you can do","slug":"what-you-can-do","link":"#what-you-can-do","children":[]},{"level":2,"title":"Is it for me?","slug":"is-it-for-me","link":"#is-it-for-me","children":[]},{"level":2,"title":"More guides (same friendly tone)","slug":"more-guides-same-friendly-tone","link":"#more-guides-same-friendly-tone","children":[]},{"level":2,"title":"A note on privacy & trust","slug":"a-note-on-privacy-trust","link":"#a-note-on-privacy-trust","children":[]}],"relativePath":"replybridge/index.md"}'),o={name:"replybridge/index.md"},n=a('<h1 id="replybridge" tabindex="-1">ReplyBridge <a class="header-anchor" href="#replybridge" aria-hidden="true">#</a></h1><p><strong>ReplyBridge</strong> helps you handle Instagram <strong>comments and DMs</strong> faster. When someone comments on your post, it can automatically send them a <strong>private DM</strong> you wrote in advance and/or leave a <strong>public reply</strong> under their comment—so you spend less time typing the same answers.</p><p>This site is written for <strong>creators, shop owners, and social marketers</strong> who use Instagram every day. You don’t need a technical background.</p><hr><h2 id="start-here-from-instagram" tabindex="-1">Start here (from Instagram) <a class="header-anchor" href="#start-here-from-instagram" aria-hidden="true">#</a></h2><p><strong>New here?</strong> Follow the guide we link in DMs—it walks you from <strong>download to your first automated reply</strong> in simple steps:</p><p>👉 <strong><a href="/replybridge/getting-started">Get started — install &amp; set up</a></strong></p><p><strong>Install the app:</strong> <a href="https://apps.apple.com/us/app/replybridge/id6761187664" target="_blank" rel="noreferrer">ReplyBridge on the App Store</a></p><p>The <strong>getting started</strong> page is the best link to put in posts or Stories when you say things like <em>“Comment and we’ll send you the steps.”</em></p><hr><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-hidden="true">#</a></h2><table><thead><tr><th>Feature</th><th>In everyday words</th></tr></thead><tbody><tr><td><strong>Auto DM</strong></td><td>Send a private message to people who comment—great for links, prices, or next steps.</td></tr><tr><td><strong>Auto reply</strong></td><td>Post a public answer under the comment so everyone sees it (like a mini FAQ).</td></tr><tr><td><strong>Keywords</strong></td><td>Only react when the comment includes words you care about (e.g. “sale”, “info”).</td></tr><tr><td><strong>Once per person</strong></td><td>Avoid sending the same DM over and over to the same user on one post.</td></tr><tr><td><strong>Time limit</strong></td><td>Turn automation off automatically after a date—handy for events or limited offers.</td></tr><tr><td><strong>Simple stats</strong></td><td>See how many messages went out and how many people commented—so you know what works.</td></tr></tbody></table><hr><h2 id="is-it-for-me" tabindex="-1">Is it for me? <a class="header-anchor" href="#is-it-for-me" aria-hidden="true">#</a></h2><p>ReplyBridge fits if you:</p><ul><li>Run a <strong>Business</strong> or <strong>Creator</strong> Instagram and get lots of similar questions in comments or DMs.</li><li>Want to <strong>save time</strong> without ignoring your audience.</li><li>Prefer clear, <strong>Instagram-approved</strong> behavior instead of risky unofficial bots.</li></ul><hr><h2 id="more-guides-same-friendly-tone" tabindex="-1">More guides (same friendly tone) <a class="header-anchor" href="#more-guides-same-friendly-tone" aria-hidden="true">#</a></h2><table><thead><tr><th>Page</th><th>What you’ll find</th></tr></thead><tbody><tr><td><a href="/replybridge/getting-started">Get started</a></td><td>Install → sign in → connect Instagram → first automation</td></tr><tr><td><a href="/replybridge/series/">Instagram mini-series</a></td><td><strong>6 short lessons</strong> that match our Instagram series—add more episodes anytime</td></tr><tr><td><a href="/replybridge/integration">Connect Instagram</a></td><td>If linking your account feels confusing</td></tr><tr><td><a href="/replybridge/usage">How to use</a></td><td>Keywords, timing, and day-to-day tips</td></tr><tr><td><a href="/replybridge/marketing/">Marketing &amp; tips</a></td><td>Content ideas for your own Instagram</td></tr></tbody></table><hr><h2 id="a-note-on-privacy-trust" tabindex="-1">A note on privacy &amp; trust <a class="header-anchor" href="#a-note-on-privacy-trust" aria-hidden="true">#</a></h2><p>ReplyBridge is built to work with Instagram’s <strong>official</strong> tools. You connect your account inside the app; you don’t need to “code” anything or use a separate developer console.</p><p>For policies that apply to our apps and this website, see <a href="/privacy-policy">Privacy Policy</a> and <a href="/terms">Terms</a>.</p>',23),s=[n];function i(d,l,h,g,p,m){return r(),e("div",null,s)}const y=t(o,[["render",i]]);export{u as __pageData,y as default};
